begin;
set local search_path=public,extensions;
select no_plan();

update public.brand_kits set status='READY',current_version_id='c1880000-0000-4000-8000-000000000031'where id='c1880000-0000-4000-8000-000000000030';
update public.marketing_templates set status='ACTIVE',current_version_id='c1880000-0000-4000-8000-000000000041'where id='c1880000-0000-4000-8000-000000000040';

update public.social_publication_jobs set status='RECONCILIATION_REQUIRED',attempt_count=1,lease_token='f1880000-0000-4000-8000-000000000001',claimed_by='p188-worker',claimed_at=clock_timestamp()-interval'2 minutes',lease_expires_at=clock_timestamp()-interval'1 minute'where id='c1880000-0000-4000-8000-000000000090';
create temporary table p188(kind text primary key,value jsonb);
select set_config('request.jwt.claim.sub','c1880000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"c1880000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.request_social_native_verification_v1('c1880000-0000-4000-8000-000000000090','urn:li:share:123456','f1880000-0000-4000-8000-000000000003')$$,'42501','SOCIAL_VERIFICATION_DENIED','tenant cannot fabricate a native verification request');
select set_config('request.jwt.claim.sub','c1880000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"c1880000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is(public.request_social_native_verification_v1('c1880000-0000-4000-8000-000000000090','urn:li:share:123456','f1880000-0000-4000-8000-000000000003'),(select(value->>'id')::uuid from p188 where kind='request'),'verification request uses stable idempotency');
select throws_ok($$select public.request_social_native_verification_v1('c1880000-0000-4000-8000-000000000090','urn:li:share:other','f1880000-0000-4000-8000-000000000003')$$,'22000','IDEMPOTENCY_PAYLOAD_MISMATCH','changed native post cannot reuse verification key');
select is((select count(*)from public.event_outbox where event_type='SocialNativeVerificationRequestedV1'and aggregate_id=(select value->>'id'from p188 where kind='request')),1::bigint,'request has one durable worker event');
select ok(not has_function_privilege('authenticated','public.complete_social_native_verification_v1(uuid,text,timestamptz)','EXECUTE'),'operator cannot directly stamp a provider proof');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is((select value->>'account_reference'from p188 where kind='work'),'urn:li:organization:123','proof is bound to original calendar account');
select is((select value->'job'->>'provider_idempotency_key'from p188 where kind='work'),'original-request-key-p188','verification retains original claim identity');
select is((select status from public.social_publication_jobs where id='c1880000-0000-4000-8000-000000000090'),'RECONCILIATION_REQUIRED','request and proof loading do not publish or requeue');
select is(public.complete_social_native_verification_v1((select(value->>'id')::uuid from p188 where kind='request'),repeat('9',64),clock_timestamp()-interval'90 seconds')->>'outcome','SOCIAL_NATIVE_VERIFIED','verified native response can complete the original claim');
select is((select status from public.social_publication_jobs where id='c1880000-0000-4000-8000-000000000090'),'PUBLISHED','only positive native proof resolves published fact');
select ok((select count(*)=1 and min(content_hash)=repeat('1',64)and min(authorization_evidence_hash)=repeat('b',64)and min(consent_evidence_hash)=repeat('a',64)from public.marketing_publication_journal where job_id='c1880000-0000-4000-8000-000000000090'),'journal preserves original exact version and claim consent evidence');
select ok((select published_at<clock_timestamp()-interval'80 seconds'and published_at>clock_timestamp()-interval'100 seconds'from public.marketing_publication_journal where job_id='c1880000-0000-4000-8000-000000000090'),'journal keeps actual provider publication time instead of late reconciliation time');
select is(public.prepare_social_native_verification_v1((select(value->>'id')::uuid from p188 where kind='request'))->>'outcome','SOCIAL_ALREADY_VERIFIED','retry does not query or post again');
select throws_ok($$select public.complete_social_native_verification_v1((select(value->>'id')::uuid from p188 where kind='request'),repeat('f',64),clock_timestamp()-interval'90 seconds')$$,'22000','SOCIAL_NATIVE_REPLAY_MISMATCH','different proof cannot overwrite immutable resolution');
select is((select count(*)from public.social_publication_results where job_id='c1880000-0000-4000-8000-000000000090'),1::bigint,'no duplicate publication result is created');
select*from finish();
rollback;
